import{_ as t,o as e,c as a,a2 as i}from"./chunks/framework.CZo9GF0W.js";const k=JSON.parse('{"title":"Supabase","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/supabase.md","filePath":"recipes/supabase.md","lastUpdated":1789060268000}'),o={name:"recipes/supabase.md"};function n(r,s,d,h,l,p){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="supabase" tabindex="-1">Supabase <a class="header-anchor" href="#supabase" aria-label="Permalink to &quot;Supabase&quot;">​</a></h1><p>Supabase gives you three connection strings and they are not interchangeable. Pick by what you are doing.</p><table tabindex="0"><thead><tr><th></th><th>Direct connection</th><th>Session pooler</th><th>Transaction pooler</th></tr></thead><tbody><tr><td>Port</td><td>5432</td><td>6543</td><td>6543</td></tr><tr><td>Host</td><td><code>db.&lt;ref&gt;.supabase.co</code></td><td><code>aws-0-&lt;region&gt;.pooler.supabase.com</code></td><td><code>aws-0-&lt;region&gt;.pooler.supabase.com</code></td></tr><tr><td>User</td><td><code>postgres</code></td><td><code>postgres.&lt;ref&gt;</code></td><td><code>postgres.&lt;ref&gt;</code></td></tr><tr><td>IPv4</td><td>add-on required</td><td>yes</td><td>yes</td></tr><tr><td>Prepared statements</td><td>yes</td><td>yes</td><td><strong>no</strong></td></tr><tr><td>Good for Pitta</td><td><strong>yes</strong></td><td>yes</td><td>no</td></tr></tbody></table><p><strong>Use the direct connection or the session pooler.</strong> The transaction pooler hands you a different backend per transaction, which breaks prepared statements, session settings, temporary tables and cursors — and the grid pages results with a cursor.</p><h2 id="the-profile" tabindex="-1">The profile <a class="header-anchor" href="#the-profile" aria-label="Permalink to &quot;The profile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>db.abcdefghijklm.supabase.co</code></td></tr><tr><td>Port</td><td><code>5432</code></td></tr><tr><td>Database</td><td><code>postgres</code></td></tr><tr><td>User</td><td><code>postgres</code></td></tr><tr><td>Password</td><td>the database password from <strong>Project Settings → Database</strong>, not your Supabase account password and not the <code>anon</code> key</td></tr><tr><td>SSL mode</td><td><code>verify-full</code></td></tr><tr><td>Environment</td><td><code>prod</code> — a Supabase project is somebody&#39;s production, including yours</td></tr></tbody></table><p>Supabase&#39;s certificate chains to a public CA, so no CA file is needed. The project settings page also offers a certificate download if you want to pin it.</p><h2 id="ipv4" tabindex="-1">IPv4 <a class="header-anchor" href="#ipv4" aria-label="Permalink to &quot;IPv4&quot;">​</a></h2><p>Direct connections are IPv6-only unless you have the IPv4 add-on. If your network is IPv4-only, <code>db.&lt;ref&gt;.supabase.co</code> will not resolve to anything you can reach — use the session pooler, which is dual-stack.</p><p>Under Remote-SSH this is the remote&#39;s connectivity that matters, not your laptop&#39;s.</p><h2 id="what-you-will-see" tabindex="-1">What you will see <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What you will see&quot;">​</a></h2><p><code>auth</code>, <code>storage</code>, <code>realtime</code> and <code>extensions</code> schemas alongside <code>public</code>. They are the platform&#39;s, and they are worth leaving alone. <code>pitta.explorer.showSystemObjects</code> does not hide them, because they are not system schemas — they are ordinary schemas that belong to Supabase.</p><p>Row Level Security policies show under a table&#39;s <strong>Structure</strong> tab. Note that connecting as <code>postgres</code> <strong>bypasses RLS</strong>: you are seeing every row, not the rows an application user would see. That is the point of a superuser connection and the reason to be careful with it.</p><h2 id="read-only-access" tabindex="-1">Read-only access <a class="header-anchor" href="#read-only-access" aria-label="Permalink to &quot;Read-only access&quot;">​</a></h2><p>Make a scoped role and use it for the profile you leave open all day:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pitta_ro </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">login</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;chosen-password&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">grant</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> connect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> on</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> postgres </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pitta_ro;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">grant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> usage </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">on</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> public </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pitta_ro;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">grant</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> all tables </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> public </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pitta_ro;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">alter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> privileges </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> public </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">grant</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tables </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pitta_ro;</span></span></code></pre></div><p>Tick <strong>Read-only</strong> on the profile as well. The server enforces it and Pitta refuses to send the statement in the first place.</p>`,17)])])}const g=t(o,[["render",n]]);export{k as __pageData,g as default};
